window.PPP_COMPONENT_HTML = {"components/layout/footer.html":"  <footer class=\"footer\">Pratik´s Progress Plan (PPP) • Progress is a system, not a mood.</footer>\n","components/layout/header.html":"  <header class=\"topbar glass\">\n    <div class=\"brand\"><div class=\"logo\">⚡</div><div><div>Pratik´s Progress Plan</div><small style=\"color:var(--muted);font-weight:700\">PPP • Personal Progress System</small></div></div>\n    <div class=\"month-switch\">\n      <button class=\"icon-btn\" id=\"prevMonth\">‹</button>\n      <div class=\"month-label\" id=\"monthLabel\">August 2026</div>\n      <button class=\"icon-btn\" id=\"nextMonth\">›</button>\n    </div>\n    <div class=\"top-actions\">\n      <div class=\"network-status\" id=\"networkStatus\" role=\"status\"><span></span><strong>Online</strong></div>\n      <button class=\"btn primary\" id=\"quickBtn\">+ Check-in</button>\n      <div class=\"nav-more header-more\">\n        <button id=\"navMoreBtn\" class=\"btn nav-more-btn\" type=\"button\" aria-label=\"More sections and tools\" title=\"More\" aria-expanded=\"false\" aria-controls=\"navMoreMenu\"><span>•••</span></button>\n        <div class=\"nav-more-menu hidden\" id=\"navMoreMenu\">\n          <div class=\"nav-more-label\">More sections</div>\n          <button data-tab=\"activity\"><span>◉</span><div><strong>Digital Activity</strong><small>Screen-time insights</small></div></button>\n          <button data-tab=\"insights\"><span>✦</span><div><strong>Smart Insights</strong><small>Patterns and guidance</small></div></button>\n          <div class=\"nav-more-rule\"></div>\n          <button data-tab=\"settings\"><span>⚙</span><div><strong>Settings</strong><small>Preferences and data</small></div></button>\n          <button type=\"button\" id=\"themeBtn\"><span>◐</span><div><strong>Change theme</strong><small>Switch light or dark mode</small></div></button>\n          <div class=\"nav-more-label\">Data tools</div>\n          <button type=\"button\" id=\"navExportBtn\"><span>⇩</span><div><strong>Export Backup</strong><small>Download all PPP data</small></div></button>\n          <button type=\"button\" id=\"navImportBtn\"><span>⇧</span><div><strong>Import Backup</strong><small>Restore a backup file</small></div></button>\n          <button type=\"button\" id=\"navCsvBtn\"><span>▦</span><div><strong>Export CSV</strong><small>Current month spreadsheet</small></div></button>\n        </div>\n      </div>\n    </div>\n  </header>\n\n","components/layout/hero.html":"  <section class=\"hero\">\n    <div class=\"hero-grid\">\n      <div>\n        <div class=\"hero-quote-meta\"><span class=\"eyebrow\">🧠 Daily perspective • Built for your goals</span><span id=\"heroQuoteCount\">1 / 60</span></div>\n        <h1 class=\"hero-quote\" id=\"heroQuote\"><span class=\"gradient-text\" id=\"heroQuoteText\">Fall in love with the process, and the results will follow.</span></h1>\n        <p>Career preparation, system design, machine learning, language learning, focused study, and reading—organized into one repeatable personal progress system.</p>\n        <div class=\"hero-actions\">\n          <button class=\"btn green\" id=\"todayHeroBtn\">Complete Today's Check-in</button>\n          <button class=\"btn primary\" id=\"nextDayHeroBtn\">✦ Plan Next Day →</button>\n        </div>\n      </div>\n      <div class=\"readiness\">\n        <div class=\"ring\">\n          <svg viewBox=\"0 0 200 200\">\n            <defs><linearGradient id=\"ringGradient\"><stop stop-color=\"#27d6e8\"/><stop offset=\"1\" stop-color=\"#9b6cff\"/></linearGradient></defs>\n            <circle class=\"bg-ring\" cx=\"100\" cy=\"100\" r=\"78\"></circle>\n            <circle class=\"value-ring\" id=\"readinessRing\" cx=\"100\" cy=\"100\" r=\"78\" stroke-dasharray=\"490.09\" stroke-dashoffset=\"490.09\"></circle>\n          </svg>\n          <div class=\"ring-content\"><div class=\"ring-number\" id=\"readinessScore\">0</div><div class=\"ring-label\">Readiness</div></div>\n        </div>\n      </div>\n    </div>\n  </section>\n\n","components/layout/navigation.html":"  <nav class=\"nav glass\" aria-label=\"Main navigation\">\n    <div class=\"nav-main\">\n      <button class=\"active\" data-tab=\"command\" aria-label=\"Command Center\" title=\"Command Center\"><span>⌂</span> Command Center</button>\n      <button data-tab=\"today\" aria-label=\"Today's Check-in\" title=\"Today's Check-in\"><span>✓</span> Today's Check-in</button>\n      <button data-tab=\"calendar\" aria-label=\"Calendar and Data\" title=\"Calendar and Data\"><span>▦</span> Calendar</button>\n      <button data-tab=\"plan\" aria-label=\"21-Day Plan\" title=\"21-Day Plan\"><span>◫</span> 21-Day Plan</button>\n      <button data-tab=\"routine\" aria-label=\"My Day Planner\" title=\"My Day Planner\"><span>☀</span> My Day</button>\n      <button id=\"nextDayNavBtn\" aria-label=\"Open Plan Next Day page\" title=\"Plan Next Day\"><span>✦</span> Plan Next Day</button>\n      <button data-tab=\"diary\" aria-label=\"My Diary\" title=\"My Diary\"><span>✎</span> My Diary</button>\n      <button data-tab=\"library\" aria-label=\"My Library\" title=\"My Library\"><span>▤</span> My Library</button>\n      <button data-tab=\"bookings\" aria-label=\"Bookings\" title=\"Bookings\"><span>▣</span> Bookings</button>\n    </div>\n  </nav>\n\n  <div class=\"box glass now-coach\" aria-live=\"polite\">\n    <div class=\"now-coach-bar\"><div class=\"now-clock\" id=\"nowCoachClock\">What should I do right now?</div><button class=\"now-collapse\" id=\"nowCoachCollapseBtn\" type=\"button\" aria-expanded=\"true\">Collapse</button></div>\n    <div class=\"now-coach-grid\" id=\"nowCoachBody\">\n      <div>\n        <div class=\"now-title\" id=\"nowCoachTitle\">Preparing your next action…</div>\n        <div class=\"now-detail\" id=\"nowCoachDetail\">The planner is checking the time and your unfinished priorities.</div>\n        <div class=\"now-reason\" id=\"nowCoachReason\">One clear action is enough. Reassess when it is finished.</div>\n        <div class=\"now-meta\" id=\"nowCoachMeta\"></div>\n      </div>\n      <div class=\"now-actions\">\n        <button class=\"btn green\" id=\"nowCoachDoBtn\">Start this</button>\n        <button class=\"btn primary\" id=\"nowCoachDoneBtn\">✓ Done</button>\n        <button class=\"btn\" id=\"nowCoachEasyBtn\">Make it easier</button>\n        <button class=\"btn\" id=\"nowCoachAnotherBtn\">Another option</button>\n        <button class=\"btn\" id=\"nowCoachRefreshBtn\">Refresh</button>\n      </div>\n    </div>\n  </div>\n","components/overlays/feedback.html":"<canvas id=\"confetti\" class=\"confetti\"></canvas>\n<div class=\"toast\" id=\"toast\"></div>\n","components/overlays/plan-progress.html":"<div id=\"planProgressModal\" class=\"modal-backdrop hidden\">\n  <div class=\"modal glass plan-progress-modal\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"planProgressTitle\">\n    <div class=\"modal-head\"><div><div class=\"plan-progress-eyebrow\">21-Day Plan · Record progress</div><h2 id=\"planProgressTitle\">Goal progress</h2></div><button class=\"icon-btn\" id=\"closePlanProgress\" type=\"button\" aria-label=\"Close\">✕</button></div>\n    <div class=\"plan-progress-context\"><div class=\"plan-progress-icon\" id=\"planProgressIcon\">✓</div><div><strong id=\"planProgressGoal\">Goal</strong><span id=\"planProgressDate\">Scheduled date</span></div><div class=\"plan-progress-target\"><strong id=\"planProgressTarget\">0 min</strong><span>Target</span></div></div>\n    <label class=\"plan-progress-field\"><span>Total minutes completed</span><div class=\"plan-progress-input\"><input id=\"planProgressMinutes\" type=\"number\" min=\"0\" max=\"1440\" step=\"1\" inputmode=\"numeric\"><strong>minutes</strong></div></label>\n    <input class=\"plan-progress-range\" id=\"planProgressRange\" type=\"range\" min=\"0\" max=\"120\" step=\"5\">\n    <div class=\"plan-progress-quick\" id=\"planProgressQuick\"></div>\n    <div class=\"plan-progress-preview\" id=\"planProgressPreview\">Choose the actual total. PPP will update every connected progress view.</div>\n    <div class=\"modal-actions\"><button class=\"btn\" id=\"cancelPlanProgress\" type=\"button\">Cancel</button><button class=\"btn green\" id=\"savePlanProgress\" type=\"button\">Save &amp; Sync</button></div>\n  </div>\n</div>\n","components/overlays/quick-checkin.html":"<div id=\"quickModal\" class=\"modal-backdrop hidden\">\n  <div class=\"modal glass\">\n    <div class=\"modal-head\"><h2>⚡ Quick Check-in</h2><button class=\"icon-btn\" id=\"closeQuick\">✕</button></div>\n    <p class=\"k-sub\">Choose a mode. You can refine details in Today's Check-in.</p>\n    <div class=\"quick-grid\" style=\"grid-template-columns:repeat(2,1fr)\">\n      <button class=\"input-card glass btn\" data-quick=\"minimum\"><strong>Minimum Progress Day</strong><div class=\"k-sub\">Audi 25m, Coursera ML 15m, German 15m.</div></button>\n      <button class=\"input-card glass btn\" data-quick=\"solid\"><strong>Focused Career Day</strong><div class=\"k-sub\">Audi, System Design, Coursera ML, and German.</div></button>\n      <button class=\"input-card glass btn\" data-quick=\"full\"><strong>Full Target Day</strong><div class=\"k-sub\">Apply every configured daily goal target.</div></button>\n      <button class=\"input-card glass btn\" data-quick=\"recovery\"><strong>Reading Recovery Day</strong><div class=\"k-sub\">Motivational, German story, and spoken-English reading.</div></button>\n    </div>\n    <div class=\"modal-actions\"><button class=\"btn\" id=\"openDetailed\">Open Detailed Check-in</button></div>\n  </div>\n</div>\n\n","components/overlays/tools-menu.html":"<div id=\"toolsMenu\" class=\"modal-backdrop hidden\">\n  <div class=\"modal glass\" style=\"width:min(480px,100%)\">\n    <div class=\"modal-head\"><h2>Data Tools</h2><button class=\"icon-btn\" id=\"closeTools\">✕</button></div>\n    <div class=\"hero-actions\"><button class=\"btn primary\" id=\"menuExport\">Export Backup</button><button class=\"btn\" id=\"menuCsv\">Export CSV</button><button class=\"btn\" id=\"menuSettings\">Settings</button></div>\n  </div>\n</div>\n\n","components/sections/activity.html":"  <section id=\"activity\" class=\"panel\">\n    <div class=\"section-head\">\n      <div><h2>Digital Activity</h2><p>Automatic active-tab timing from the private PPP Chrome extension.</p></div>\n      <div style=\"display:flex;gap:8px;flex-wrap:wrap\"><button class=\"btn\" id=\"refreshActivityBtn\">Refresh</button><button class=\"btn\" id=\"exportActivityBtn\">Export Activity</button></div>\n    </div>\n\n    <div class=\"activity-connect glass\">\n      <div class=\"connection-left\">\n        <div class=\"connection-dot waiting\" id=\"activityConnectionDot\"></div>\n        <div><strong id=\"activityConnectionTitle\">Looking for the PPP Activity Tracker…</strong><div class=\"k-sub\" id=\"activityConnectionText\">Install the extension once; PPP itself does not need to stay open.</div></div>\n      </div>\n      <button class=\"btn primary\" id=\"activityInstallHelpBtn\">Installation Guide</button>\n    </div>\n\n    <div class=\"activity-cards\">\n      <div class=\"card glass activity-card\" style=\"--activity-accent:var(--blue)\"><div class=\"k-label\">Active browser time</div><div class=\"activity-value\" id=\"activityTotal\">—</div><div class=\"activity-sub\">Today while Chrome was focused</div></div>\n      <div class=\"card glass activity-card\" style=\"--activity-accent:var(--green)\"><div class=\"k-label\">Productive + study</div><div class=\"activity-value\" id=\"activityProductive\">—</div><div class=\"activity-sub\">Focused digital work</div></div>\n      <div class=\"card glass activity-card\" style=\"--activity-accent:var(--pink)\"><div class=\"k-label\">Social + entertainment</div><div class=\"activity-value\" id=\"activityDistracting\">—</div><div class=\"activity-sub\">Potential distraction time</div></div>\n      <div class=\"card glass activity-card\" style=\"--activity-accent:var(--cyan)\"><div class=\"k-label\">Digital focus ratio</div><div class=\"activity-value\" id=\"activityFocusRatio\">—</div><div class=\"activity-sub\">Productive share of intentional time</div></div>\n      <div class=\"card glass activity-card\" style=\"--activity-accent:var(--gold)\"><div class=\"k-label\">Websites visited</div><div class=\"activity-value\" id=\"activityDomainCount\">—</div><div class=\"activity-sub\">Unique domains today</div></div>\n    </div>\n\n    <div class=\"grid2\" style=\"margin-top:13px\">\n      <div class=\"box glass\"><h3>Last 7 days</h3><div class=\"box-sub\">Total active browsing and productive time.</div><canvas class=\"chart\" id=\"activityWeekChart\"></canvas></div>\n      <div class=\"box glass\"><h3>Today's categories</h3><div class=\"box-sub\">You can recategorize any website below.</div><div class=\"activity-bars\" id=\"activityCategoryBars\" style=\"margin-top:16px\"></div><div class=\"activity-legend\" id=\"activityLegend\"></div></div>\n    </div>\n\n    <div class=\"grid2\" style=\"margin-top:13px\">\n      <div class=\"box glass\">\n        <h3>Top websites today</h3>\n        <div class=\"box-sub\">Only the domain and active seconds are stored—never full URLs, page titles, or searches.</div>\n        <div style=\"overflow:auto;margin-top:10px\">\n          <table class=\"activity-table\"><thead><tr><th>Website</th><th>Active time</th><th>Share</th><th>Category</th></tr></thead><tbody id=\"activityDomainRows\"></tbody></table>\n        </div>\n      </div>\n      <div>\n        <div class=\"box glass\">\n          <h3>Live tracker</h3>\n          <div class=\"live-domain\" style=\"margin-top:12px\"><div class=\"live-pulse\" id=\"activityLivePulse\"></div><div><strong id=\"activityLiveDomain\">Waiting for extension</strong><div class=\"k-sub\" id=\"activityLiveStatus\">Tracking begins automatically after installation.</div></div></div>\n          <div class=\"activity-controls\" style=\"margin-top:13px\">\n            <div class=\"control-row\"><div><strong>Automatic tracking</strong><span>Pause without uninstalling the extension.</span></div><button class=\"btn\" id=\"activityTrackingBtn\">—</button></div>\n            <div class=\"control-row\"><div><strong>Idle cutoff</strong><span>Stop counting after no keyboard or mouse activity.</span></div><select id=\"activityIdleSelect\"><option value=\"30\">30 sec</option><option value=\"60\">60 sec</option><option value=\"120\">2 min</option><option value=\"300\">5 min</option></select></div>\n          </div>\n        </div>\n        <div class=\"privacy-note\" style=\"margin-top:13px\">\n          <strong style=\"color:var(--text)\">Privacy design:</strong> all activity remains in <code>chrome.storage.local</code> on this Chrome profile. The extension does not use a database, does not read page content, and does not upload browsing data.\n        </div>\n      </div>\n    </div>\n  </section>\n\n","components/sections/bookings.html":"<section id=\"bookings\" class=\"panel\">\n  <div class=\"section-head booking-dashboard-head\"><div><h2>📅 Booking Dashboard</h2><p>Share your page, review incoming requests, and synchronize accepted appointments with My Day.</p></div><button class=\"btn primary\" id=\"refreshBookingRequestsBtn\">↻ Refresh Requests</button></div>\n  <div class=\"booking-dashboard-stats\" id=\"bookingDashboardStats\"></div>\n  <div class=\"box glass booking-share-card\"><div><h3>Your public booking page</h3><p>Anyone with this link can request a time. Your PPP data and admin key are never shown.</p></div><div class=\"booking-share-bar\"><input id=\"publicBookingLink\" readonly placeholder=\"Connect the service in Settings\"><button class=\"btn primary\" id=\"copyBookingLinkBtn\">Copy Link</button><button class=\"btn\" id=\"openPublicBookingBtn\">Open</button></div><div class=\"booking-connection-note\" id=\"bookingConnectionNote\">Connect the booking service in Settings first.</div></div>\n  <div class=\"section-head booking-subhead\"><div><h2>Incoming requests</h2><p>Accept a request to add it to Bookings, Google Calendar, and your Daily Planner.</p></div></div>\n  <div class=\"box glass\" id=\"bookingRequestList\"><div class=\"booking-empty\">Connect the booking service, then refresh.</div></div>\n  <div class=\"section-head booking-subhead\"><div><h2>Accepted bookings</h2><p>Private feedback is stored only in this browser.</p></div></div>\n  <div id=\"bookingPanelList\" class=\"booking-panel-list\"></div>\n</section>\n","components/sections/calendar.html":"  <section id=\"calendar\" class=\"panel\">\n    <div class=\"section-head\">\n      <div><h2>Calendar & Data</h2><p>Your ten learning goals, sleep, notes, and daily progress in one editable timeline.</p></div>\n      <div style=\"display:flex;gap:8px;flex-wrap:wrap\">\n        <button class=\"btn\" id=\"tableStartBtn\">Start of Table</button>\n        <button class=\"btn\" id=\"jumpTodayBtn\">Jump to Today</button>\n      </div>\n    </div>\n    <div class=\"table-wrap\" id=\"calendarTableWrap\">\n      <table class=\"calendar-table\">\n        <thead><tr id=\"calendarHeadRow\"></tr></thead>\n        <tbody id=\"dataBody\"></tbody>\n      </table>\n    </div>\n  </section>\n\n\n","components/sections/dashboard.html":"  <section id=\"command\" class=\"panel active\">\n    <div class=\"section-head\"><div><h2>Command Center</h2><p>Live view of momentum, health, focus, and risk.</p></div></div>\n    <div class=\"cards\">\n      <div class=\"card glass\" style=\"--accent:var(--gold)\"><div class=\"k-label\">Total points</div><div class=\"k-value\" id=\"totalPoints\">0</div><div class=\"k-sub\" id=\"rewardLevel\">Starter</div><span class=\"trend flat\" id=\"pointsTrend\">No trend yet</span></div>\n      <div class=\"card glass\" style=\"--accent:var(--teal)\"><div class=\"k-label\">Completion</div><div class=\"k-value\" id=\"completion\">0%</div><div class=\"k-sub\">Across logged days</div><span class=\"trend flat\" id=\"completionTrend\">No trend yet</span></div>\n      <div class=\"card glass\" style=\"--accent:var(--purple)\"><div class=\"k-label\">Current streak</div><div class=\"k-value\" id=\"currentStreak\">0</div><div class=\"k-sub\">Mission days</div><span class=\"trend flat\" id=\"streakStatus\">Ready to start</span></div>\n      <div class=\"card glass\" style=\"--accent:var(--cyan)\"><div class=\"k-label\">Sleep average</div><div class=\"k-value\" id=\"avgSleep\">—</div><div class=\"k-sub\">Hours per logged night</div><span class=\"trend flat\" id=\"sleepTrend\">No sleep data</span></div>\n      <div class=\"card glass\" style=\"--accent:var(--green)\"><div class=\"k-label\">Career readiness</div><div class=\"k-value\" id=\"disciplineScore\">0</div><div class=\"k-sub\">Audi + System Design + Coursera ML</div><span class=\"trend flat\" id=\"disciplineTrend\">Build the baseline</span></div>\n    </div>\n\n    <div class=\"grid3\" style=\"margin-top:13px\">\n      <div class=\"box glass ai-box\">\n        <div class=\"ai-head\"><h3>Smart Coach</h3><span class=\"ai-pill\">✦ Local pattern engine</span></div>\n        <div class=\"ai-message\" id=\"coachHeadline\">Your system is ready. Start with one honest day.</div>\n        <div class=\"ai-list\" id=\"coachPriorities\"></div>\n      </div>\n      <div class=\"box glass\">\n        <h3>Monthly forecast</h3><div class=\"box-sub\">Projected from your current pace</div>\n        <div class=\"k-value\" id=\"forecastPoints\">0</div><div class=\"k-sub\">projected points</div>\n        <div style=\"margin-top:14px\"><div class=\"track\"><div class=\"fill\" id=\"forecastBar\"></div></div></div>\n        <div class=\"k-sub\" id=\"forecastText\" style=\"margin-top:9px\">Log a few days to generate a forecast.</div>\n      </div>\n      <div class=\"box glass\">\n        <h3>Mission risk</h3><div class=\"box-sub\">Smart warning before momentum breaks</div>\n        <div class=\"k-value\" id=\"riskLevel\">Low</div>\n        <div class=\"k-sub\" id=\"riskText\">No risk detected.</div>\n        <div class=\"badges\" id=\"achievementMini\" style=\"margin-top:14px\"></div>\n      </div>\n    </div>\n\n    <section class=\"box glass habit-coach\" id=\"habitCoachBlueprint\">\n      <div class=\"habit-coach-head\"><div><div class=\"diary-review-kicker\">Personal coaching loop</div><h3>Your Consistency Blueprint</h3><p id=\"habitCoachSummary\">One repeatable action, reviewed and improved every week.</p></div><span class=\"habit-phase\" id=\"habitCoachPhase\">Foundation</span></div>\n      <div class=\"habit-coach-grid\" id=\"habitCoachSteps\"></div>\n      <div class=\"habit-coach-footer\"><p id=\"habitCoachRule\">Never miss twice. A reduced day still protects the habit.</p><div><button class=\"btn green\" id=\"applyCoachMinimum\">Apply Today’s Minimum</button><button class=\"btn\" id=\"openCoachDiary\">Review My Diary</button></div></div>\n    </section>\n\n    <div class=\"grid2\" style=\"margin-top:13px\">\n      <div class=\"box glass\"><h3>Weekly momentum</h3><canvas class=\"chart\" id=\"weeklyChart\"></canvas></div>\n      <div class=\"box glass\"><h3>Habit completion</h3><div class=\"progress-list\" id=\"habitBars\"></div></div>\n      <div class=\"box glass\"><h3>Sleep duration & target</h3><canvas class=\"chart\" id=\"sleepChart\"></canvas></div>\n      <div class=\"box glass\"><h3>Consistency heatmap</h3><div class=\"heatmap\" id=\"heatmap\"></div><div class=\"box-sub\" style=\"margin-top:10px\">Darker days = stronger completion.</div></div>\n    </div>\n\n    <div class=\"grid2\" style=\"margin-top:13px\">\n      <div class=\"box glass\">\n        <h3>Achievements</h3><div class=\"box-sub\">Milestones unlock automatically.</div><div class=\"badges\" id=\"achievements\"></div>\n      </div>\n      <div class=\"box glass focus-card\" id=\"focusSprintBox\">\n        <div class=\"focus-card-head\">\n          <div><div class=\"focus-eyebrow\"><span></span> Deep work studio</div><h3>Flexible Focus Timer</h3><div class=\"box-sub\">Choose one priority. Give it your full attention.</div></div>\n          <div class=\"timer-mode\" id=\"timerModes\">\n            <button class=\"mode-btn active\" data-timer-mode=\"stopwatch\">↗ Count Up</button>\n            <button class=\"mode-btn\" data-timer-mode=\"countdown\">◷ Countdown</button>\n          </div>\n        </div>\n        <div class=\"focus-panel\">\n          <div class=\"timer-stage\">\n            <div class=\"timer-orbit\"><div class=\"timer-orbit-inner\"><div class=\"timer-label\">FOCUS TIME</div><div class=\"timer\" id=\"timerDisplay\">00:00</div><div class=\"timer-focus-label\" id=\"timerFocusLabel\">Choose a focus</div></div></div>\n          </div>\n          <div class=\"focus-setup\">\n            <div class=\"focus-step-label\"><span>1</span> What are you focusing on?</div>\n            <div class=\"focus-select\" id=\"focusSelect\"></div>\n            <div class=\"duration-tools hidden-tool\" id=\"durationTools\">\n              <div class=\"focus-step-label\"><span>2</span> Choose a target</div>\n              <div class=\"duration-options\"><div id=\"durationPresets\"></div><div class=\"duration-custom\"><input id=\"customDuration\" type=\"number\" min=\"1\" max=\"240\" step=\"1\" value=\"25\" aria-label=\"Custom minutes\"><span>min</span></div></div>\n            </div>\n            <div class=\"timer-controls\">\n              <button class=\"btn primary timer-start\" id=\"timerStart\">▶ Start Focus</button>\n              <button class=\"btn\" id=\"timerPause\">Pause</button>\n              <button class=\"btn finish-btn\" id=\"timerFinish\">✓ Finish & Save</button>\n              <button class=\"btn timer-reset\" id=\"timerReset\" title=\"Reset timer\">↻</button>\n            </div>\n            <div class=\"timer-status\" id=\"timerStatus\">Choose a study habit, press Start, and finish whenever your real focus session ends.</div>\n          </div>\n        </div>\n        <div class=\"focus-music\" id=\"focusMusicPanel\">\n          <div class=\"music-identity\"><div class=\"music-art\">♫</div><div><div class=\"focus-music-title\">Built-in Focus Sound</div><div class=\"focus-music-sub\">Ambient audio generated inside PPP—no account, link, or internet connection required.</div></div></div>\n          <div class=\"music-settings\">\n            <select id=\"musicPreset\" aria-label=\"Focus sound\"><option value=\"deep\">Deep Focus</option><option value=\"brown\">Brown Noise</option><option value=\"rain\">Soft Rain</option></select>\n            <button class=\"btn music-play\" id=\"musicPlayPause\">▶ Play Sound</button>\n            <label class=\"music-volume\"><span>Volume</span><input id=\"musicVolume\" type=\"range\" min=\"0\" max=\"100\" value=\"35\"><strong id=\"musicVolumeValue\">35%</strong></label>\n          </div>\n          <div class=\"music-footer\"><label class=\"music-toggle\"><input type=\"checkbox\" id=\"musicWithTimer\" checked><span>Follow timer automatically</span></label><div class=\"music-status\" id=\"musicStatus\">Choose a sound, press Play, or start the focus timer.</div></div>\n        </div>\n      </div>\n    </div>\n  </section>\n\n","components/sections/diary.html":"<section id=\"diary\" class=\"panel\">\n  <div class=\"section-head\">\n    <div><h2>My Diary</h2><p>Capture thoughts, plans, tasks, summaries, and moments. You decide whether each entry is kept or expires.</p></div>\n    <div class=\"diary-retention\">🔒 Private on this device</div>\n  </div>\n\n  <div class=\"diary-layout\">\n    <div class=\"box glass diary-composer\">\n      <div class=\"diary-current-time\"><span>Entry date and time</span><strong id=\"diaryCurrentDateTime\">—</strong></div>\n      <div class=\"diary-composer-head\">\n        <div><h3>Write something</h3><div class=\"box-sub\">What is on your mind right now?</div></div>\n        <select id=\"diaryType\" aria-label=\"Entry type\">\n          <option value=\"thought\">Thought</option>\n          <option value=\"task\">Task or plan</option>\n          <option value=\"summary\">Daily summary</option>\n          <option value=\"win\">Win or achievement</option>\n          <option value=\"note\">Quick note</option>\n        </select>\n      </div>\n      <input id=\"diaryTitle\" type=\"text\" maxlength=\"120\" placeholder=\"Title (optional)\" aria-label=\"Entry title\">\n      <textarea id=\"diaryText\" maxlength=\"10000\" placeholder=\"Write freely here…\" aria-label=\"Diary entry\"></textarea>\n      <div class=\"diary-attachment-tools\">\n        <input id=\"diaryImageInput\" type=\"file\" accept=\"image/jpeg,image/png,image/webp,image/gif\" hidden>\n        <button class=\"btn diary-image-button\" type=\"button\" id=\"diaryImageButton\">🖼 Add Image</button>\n        <span>JPG, PNG, WebP, or GIF · automatically optimized</span>\n      </div>\n      <div class=\"diary-image-preview hidden\" id=\"diaryImagePreview\">\n        <img id=\"diaryImagePreviewImg\" alt=\"Selected diary attachment\">\n        <div><strong id=\"diaryImagePreviewName\">Image selected</strong><span id=\"diaryImagePreviewSize\"></span></div>\n        <button type=\"button\" id=\"diaryImageRemove\" aria-label=\"Remove selected image\">✕</button>\n      </div>\n      <label class=\"diary-auto-delete\">\n        <input id=\"diaryAutoDelete\" type=\"checkbox\">\n        <span><strong>Delete this entry automatically after 7 days</strong><small>Leave this unchecked to keep the entry until you delete it yourself.</small></span>\n      </label>\n      <label class=\"diary-auto-delete\"><input id=\"diaryExcludeAI\" type=\"checkbox\"><span><strong>Keep this entry out of Gemini reviews</strong><small>The entry remains available to the private local review.</small></span></label>\n      <label class=\"diary-auto-delete\"><input id=\"diaryAnalyzeGemini\" type=\"checkbox\" checked><span><strong>Analyze this entry with Gemini</strong><small>Gemini interprets the text; PPP validates and applies only safe, supported planner outcomes.</small></span></label>\n      <div class=\"diary-compose-footer\">\n        <span id=\"diaryCharacterCount\" class=\"k-sub\">0 / 10,000</span>\n        <button class=\"btn primary\" id=\"saveDiaryEntry\">Save Entry</button>\n      </div>\n      <p class=\"diary-hint\">Tip: press Ctrl + Enter to save. Entries are stored only in this browser.</p>\n      <p class=\"diary-hint\">✦ Gemini interprets meaning and returns structured outcomes. PPP accepts only known goals, explicit minutes, valid dates, schedule preferences, and commitments.</p>\n    </div>\n\n    <aside class=\"box glass diary-about\">\n      <h3>This week at a glance</h3>\n      <div class=\"diary-stats\">\n        <div><strong id=\"diaryEntryCount\">0</strong><span>active entries</span></div>\n        <div><strong id=\"diaryWordCount\">0</strong><span>words written</span></div>\n      </div>\n      <div class=\"diary-rule\"></div>\n      <p>Entries are kept by default. When saving, you can optionally make an entry disappear seven days later.</p>\n      <button class=\"btn danger\" id=\"clearDiaryEntries\">Delete All Entries</button>\n    </aside>\n  </div>\n\n  <section class=\"box glass consistency-checkin\">\n    <div class=\"diary-review-head\"><div><div class=\"diary-review-kicker\">Automatic habit recovery</div><h3>Consistency Coach</h3><p>Automatically combines your Day progress, calendar commitments, sleep, active goals, and diary patterns. No duplicate input required.</p></div><button class=\"btn\" id=\"refreshConsistencyCoach\" type=\"button\">Refresh</button></div>\n    <div id=\"consistencyWeekSummary\"></div>\n  </section>\n\n  <section class=\"box glass diary-review\" id=\"diaryDailyReview\">\n    <div class=\"diary-review-head\"><div><div class=\"diary-review-kicker\">✦ Gemini diary intelligence</div><h3>My Progress Review</h3><p>Today combines the validated Gemini outcomes saved with each entry. Period reviews ask Gemini to analyze the selected entries together.</p><label class=\"gemini-consent\"><input type=\"checkbox\" id=\"geminiReviewConsent\"> I understand that included diary text will be sent to Google Gemini for this period review.</label></div><div class=\"diary-review-actions\"><button class=\"btn\" id=\"refreshDiaryReview\">Gemini Outcomes · Today</button><button class=\"btn\" data-gemini-review=\"day\">Gemini · Day</button><button class=\"btn\" data-gemini-review=\"week\">Gemini · Week</button><button class=\"btn\" data-gemini-review=\"all\">Gemini · All</button></div></div>\n    <div id=\"diaryReviewContent\"></div>\n  </section>\n\n  <div class=\"diary-toolbar\">\n    <div>\n      <h3>Your recent entries</h3>\n      <p class=\"k-sub\">Newest first</p>\n    </div>\n    <div class=\"diary-filters\">\n      <input id=\"diarySearch\" type=\"search\" placeholder=\"Search entries…\" aria-label=\"Search diary\">\n      <select id=\"diaryFilter\" aria-label=\"Filter diary by type\">\n        <option value=\"all\">All types</option>\n        <option value=\"thought\">Thoughts</option>\n        <option value=\"task\">Tasks and plans</option>\n        <option value=\"summary\">Daily summaries</option>\n        <option value=\"win\">Wins</option>\n        <option value=\"note\">Quick notes</option>\n      </select>\n    </div>\n  </div>\n  <div id=\"diaryEntries\" class=\"diary-entries\"></div>\n</section>\n","components/sections/insights.html":"  <section id=\"insights\" class=\"panel\">\n    <div class=\"section-head\"><div><h2>Smart Insights</h2><p>Patterns generated locally from your own data.</p></div></div>\n    <div class=\"grid2\">\n      <div class=\"box glass\"><h3>AI-style weekly review</h3><div class=\"insight-list\" id=\"weeklyReview\"></div></div>\n      <div class=\"box glass\"><h3>Habit optimizer</h3><div class=\"insight-list\" id=\"habitOptimizer\"></div></div>\n      <div class=\"box glass\"><h3>Sleep → performance analysis</h3><canvas class=\"chart\" id=\"sleepPerformanceChart\"></canvas><div class=\"k-sub\" id=\"sleepCorrelationText\"></div></div>\n      <div class=\"box glass\"><h3>Next-level plan</h3><div class=\"insight-list\" id=\"nextPlan\"></div></div>\n    </div>\n  </section>\n\n","components/sections/library.html":"<section id=\"library\" class=\"panel\">\n  <div class=\"section-head library-heading\">\n    <div><h2>📚 My Library</h2><p>Keep your books and continue from the last page you read.</p></div>\n    <div class=\"library-head-actions\"><button class=\"btn\" id=\"libraryContinueBtn\">Continue Reading</button><button class=\"btn primary\" id=\"libraryAddBtn\">+ Add Book</button></div>\n  </div>\n  <div class=\"box glass library-hero\">\n    <div class=\"library-summary\" id=\"librarySummary\"></div>\n    <div class=\"library-filter\" id=\"libraryFilter\">\n      <button class=\"active\" data-library-filter=\"all\">All books</button><button data-library-filter=\"german\">🇩🇪 German</button><button data-library-filter=\"english\">🇬🇧 English</button><button data-library-filter=\"growth\">🧠 Growth</button><button data-library-filter=\"technical\">💻 Technical</button><button data-library-filter=\"other\">Other</button><button data-library-filter=\"reading\">Currently reading</button>\n    </div>\n  </div>\n  <div class=\"library-grid\" id=\"libraryGrid\"></div>\n\n  <div class=\"modal-backdrop hidden\" id=\"bookEditorModal\">\n    <form class=\"modal glass library-editor\" id=\"bookEditorForm\">\n      <div class=\"modal-head\"><h2 id=\"bookEditorTitle\">Add Book</h2><button type=\"button\" class=\"icon-btn\" id=\"bookEditorClose\" aria-label=\"Close\">✕</button></div>\n      <input type=\"hidden\" id=\"bookEditId\">\n      <div class=\"library-form-grid\">\n        <label class=\"library-field wide\"><span>Title *</span><input id=\"bookTitle\" maxlength=\"160\" required></label>\n        <label class=\"library-field\"><span>Author</span><input id=\"bookAuthor\" maxlength=\"120\"></label>\n        <label class=\"library-field\"><span>Category</span><select id=\"bookCategory\"><option value=\"german\">German</option><option value=\"english\">English</option><option value=\"growth\">Personal Growth</option><option value=\"technical\">Technical</option><option value=\"other\">Other</option></select></label>\n        <label class=\"library-field\"><span>Icon</span><input id=\"bookIcon\" maxlength=\"12\" placeholder=\"📘\"></label>\n        <label class=\"library-field wide\"><span>Book or resource URL</span><input id=\"bookUrl\" type=\"url\" placeholder=\"https://…\"></label>\n        <label class=\"library-field wide\"><span>Purpose / description</span><textarea id=\"bookPurpose\" maxlength=\"600\"></textarea></label>\n      </div>\n      <div class=\"modal-actions\"><button type=\"button\" class=\"btn\" id=\"bookEditorCancel\">Cancel</button><button type=\"submit\" class=\"btn primary\">Save Book</button></div>\n    </form>\n  </div>\n</section>\n","components/sections/plan.html":"<section id=\"plan\" class=\"panel\">\n  <div class=\"section-head\"><div><h2>21-Day Progress Plan</h2><p>A fixed three-week cycle synchronized with Today, Calendar, and Focus Timer progress.</p></div><button class=\"btn\" id=\"planTodayBtn\">Restart from Today</button></div>\n  <div class=\"cards plan-milestones\">\n    <div class=\"card glass\" style=\"--accent:var(--blue)\"><div class=\"k-label\">Audi joining date</div><div class=\"k-value plan-date\">1 Dec 2026</div><div class=\"k-sub\" id=\"audiCountdown\">Confirmed milestone</div></div>\n    <div class=\"card glass\" style=\"--accent:var(--gold)\"><div class=\"k-label\">Coursera ML deadline</div><div class=\"k-value plan-date\">22 Oct 2026</div><div class=\"k-sub\" id=\"courseraCountdown\">Course expiry deadline</div></div>\n    <div class=\"card glass\" style=\"--accent:var(--green)\"><div class=\"k-label\">Current cycle</div><div class=\"k-value\" id=\"planCycleProgress\">0 / 63</div><div class=\"k-sub\" id=\"planCycleSummary\">Career · Technical · Language · Reading</div></div>\n  </div>\n  <div class=\"plan-legend\"><span class=\"completed\">✓ Completed</span><span class=\"partial\">◐ Partial</span><span class=\"missed\">! Missed</span><span class=\"planned\">○ Planned</span><small>Check an item to record actual minutes across PPP. Edit or remove recorded minutes in Today or Calendar.</small></div>\n  <div class=\"plan-weeks\" id=\"twentyOneDayPlan\"></div>\n</section>\n","components/sections/routine.html":"  <section id=\"routine\" class=\"panel\">\n    <div class=\"section-head\">\n      <div><h2>My Day Planner</h2><p>You do not need to choose. The planner creates one ordinary, achievable human day around your wake time and real priorities.</p></div>\n      <button class=\"btn primary\" id=\"refreshRoutineBtn\">Plan My Day</button>\n    </div>\n\n    <div class=\"box glass planner-setup\">\n      <div><h3>Before I plan your day</h3><p>Wake-up and sleep times are optional. When provided, they take priority for this date.</p></div>\n      <div class=\"planner-inputs\">\n        <label>Plan date<input id=\"routinePlanDate\" type=\"date\"></label>\n        <label>Wake-up time <span>optional</span><input id=\"routineWakeInput\" type=\"time\"></label>\n        <label>Sleep time <span>optional</span><input id=\"routineSleepInput\" type=\"time\"></label>\n        <button class=\"btn primary\" id=\"applyPlannerTimes\">Create My Plan</button>\n        <button class=\"btn\" id=\"clearPlannerTimes\">Use Default Times</button>\n      </div>\n      <div class=\"k-sub\" id=\"plannerTimeSource\">Leave both times empty to use diary preferences or your default Settings.</div>\n    </div>\n\n    <div class=\"box glass routine-hero\">\n      <div class=\"ai-head\"><div><h3 id=\"routineHeadline\">Your realistic day is being prepared.</h3><div class=\"box-sub\" id=\"routineDescription\">The plan includes focused work, meals, breaks, movement, private time, and social life.</div></div><span class=\"ai-pill\">✦ Planned for you</span></div>\n      <div class=\"routine-stats\">\n        <div class=\"routine-stat\"><strong id=\"routineWake\">07:00</strong><span>Suggested wake</span></div>\n        <div class=\"routine-stat\"><strong id=\"routineFocusTotal\">—</strong><span>Planned focused study</span></div>\n        <div class=\"routine-stat\"><strong id=\"routinePriority\">—</strong><span>Today's main outcome</span></div>\n        <div class=\"routine-stat\"><strong id=\"routineSleep\">23:00</strong><span>Target sleep</span></div>\n      </div>\n    </div>\n\n    <div class=\"grid2\" style=\"margin-top:13px\">\n      <div class=\"box glass\">\n        <h3>Today's Exact Schedule</h3>\n        <div class=\"box-sub\">Generated from your awake window. Only three learning goals are selected.</div>\n        <div class=\"routine-timeline\" id=\"routineTimeline\"></div>\n      </div>\n      <div>\n        <div class=\"box glass next-action\">\n          <h3>Best Next Action</h3>\n          <p id=\"routineNextText\">The app will choose a realistic next step from your unfinished tasks.</p>\n          <button class=\"btn green\" id=\"routineNextBtn\">Start Recommended Action</button>\n        </div>\n        <div class=\"box glass\" style=\"margin-top:13px\">\n          <h3>Fixed commitments</h3>\n          <div class=\"remaining-list\" id=\"routineCommitments\"></div>\n        </div>\n        <div class=\"box glass\" style=\"margin-top:13px\">\n          <h3>Today's chosen goals</h3>\n          <div class=\"remaining-list\" id=\"remainingPlan\"></div>\n        </div>\n        <div class=\"routine-note\" style=\"margin-top:13px\">\n          This plan intentionally leaves goals out. A human day needs food, movement, relationships, privacy, rest, and unplanned space. Completing the chosen three learning blocks is enough.\n        </div>\n      </div>\n    </div>\n  </section>\n\n\n","components/sections/settings.html":"  <section id=\"settings\" class=\"panel\">\n    <div class=\"section-head\"><div><h2>Settings & Data</h2><p>Customize the system without touching code.</p></div></div>\n    <div class=\"settings-grid\">\n      <div class=\"box glass\"><h3>Identity & experience</h3>\n        <div class=\"setting-row\"><label>Your name</label><input id=\"userName\" type=\"text\"></div>\n        <div class=\"setting-row\"><label>Monthly point target</label><input id=\"monthlyTarget\" type=\"number\" min=\"100\" max=\"3000\" step=\"50\"></div>\n        <div class=\"toggle\"><div><strong>Celebration effects</strong><div class=\"k-sub\">Confetti on mission wins</div></div><div class=\"switch\" id=\"celebrationToggle\"></div></div>\n        <div class=\"toggle\"><div><strong>Smart coach</strong><div class=\"k-sub\">Pattern-based priorities</div></div><div class=\"switch\" id=\"coachToggle\"></div></div>\n      </div>\n      <div class=\"box glass\"><h3>Sleep settings</h3>\n        <div class=\"setting-row\"><label>Target hours</label><input id=\"targetSleep\" type=\"number\" min=\"1\" max=\"14\" step=\".5\"></div>\n        <div class=\"setting-row\"><label>Short below</label><input id=\"shortBelow\" type=\"number\" min=\"1\" max=\"14\" step=\".5\"></div>\n        <div class=\"setting-row\"><label>Long above</label><input id=\"longAbove\" type=\"number\" min=\"1\" max=\"16\" step=\".5\"></div>\n        <div class=\"setting-row\"><label>Preferred sleep</label><input id=\"preferredSleep\" type=\"time\"></div>\n        <div class=\"setting-row\"><label>Preferred wake</label><input id=\"preferredWake\" type=\"time\"></div>\n        <div class=\"setting-row\"><label>Timing tolerance</label><input id=\"tolerance\" type=\"number\" min=\"0\" max=\"360\" step=\"15\"></div>\n      </div>\n      <div class=\"box glass\"><h3>Daily goal targets</h3><div id=\"goalTargetSettings\"></div>\n        <div class=\"setting-row\"><label>Mission completion threshold</label><input id=\"missionThreshold\" type=\"number\" min=\"40\" max=\"100\" step=\"5\"></div>\n      </div>\n      <div class=\"box glass\"><h3>Point weights</h3><div id=\"weightSettings\"></div></div>\n      <div class=\"box glass\"><h3>Shared booking connection</h3><div class=\"box-sub\">Connect the Google Apps Script booking service. The admin key stays in this browser.</div>\n        <div class=\"booking-setup-grid\"><label>Web app URL<input id=\"sharedBookingUrl\" type=\"url\" placeholder=\"https://script.google.com/macros/s/…/exec\"></label><label>Admin key<input id=\"sharedBookingKey\" type=\"password\" placeholder=\"Private admin key\"></label></div>\n        <div class=\"hero-actions\" style=\"margin-top:10px\"><button class=\"btn primary\" id=\"saveSharedBookingBtn\" type=\"button\">Save Connection</button><button class=\"btn\" id=\"testSharedBookingBtn\" type=\"button\">Test Connection</button><button class=\"btn green\" id=\"testBookingEmailBtn\" type=\"button\">Send Test Email</button></div><div class=\"k-sub\" id=\"sharedBookingStatus\" style=\"margin-top:9px\">Not connected yet.</div><div class=\"k-sub\" id=\"sharedBookingEmailStatus\" style=\"margin-top:6px\">Email delivery has not been tested from this deployment.</div>\n      </div>\n    </div>\n\n    <div class=\"box glass\" style=\"margin-top:13px\">\n      <h3>Backup, transfer & deployment</h3>\n      <div class=\"hero-actions\">\n        <button class=\"btn primary\" id=\"exportBtn\">Export Full Backup</button>\n        <button class=\"btn\" id=\"importBtn\">Import Backup</button>\n        <button class=\"btn\" id=\"csvBtn\">Export Current Month CSV</button>\n        <button class=\"btn\" id=\"printBtn\">Print Dashboard</button>\n        <button class=\"btn danger\" id=\"resetMonthBtn\">Reset Current Month</button>\n      </div>\n      <input type=\"file\" id=\"importFile\" accept=\".json\" hidden>\n      <p class=\"k-sub\" style=\"margin-top:12px\">Data is stored privately in this browser. Export a backup before switching devices or clearing browser data.</p>\n    </div>\n  </section>\n","components/sections/today.html":"  <section id=\"today\" class=\"panel\">\n    <div class=\"section-head\"><div><h2>Today's Check-in</h2><p id=\"todaySubtitle\">Fast, focused, and autosaved.</p></div><button class=\"btn gold\" id=\"autoSuggestBtn\">✦ Apply Smart Minimum</button></div>\n    <div class=\"quick-grid\" id=\"goalCheckinGrid\"></div>\n    <div class=\"quick-grid\" style=\"margin-top:13px\">\n      <div class=\"input-card glass\">\n        <h3>🌙 Sleep rhythm</h3><div class=\"time-grid\"><label>Sleep<input type=\"time\" id=\"sleepTime\"></label><label>Wake<input type=\"time\" id=\"wakeTime\"></label></div>\n        <div id=\"sleepPreview\" class=\"k-sub\" style=\"margin-top:10px\">Enter both times to calculate duration.</div>\n      </div>\n      <div class=\"input-card glass\" style=\"grid-column:span 2\">\n        <h3>🏅 Win / reflection</h3><textarea id=\"notes\" placeholder=\"What moved your life forward today?\"></textarea>\n      </div>\n    </div>\n    <div class=\"save-bar glass\"><div><strong id=\"todayScorePreview\">0 points • 0% completion</strong><div class=\"save-status\" id=\"saveStatus\">Changes save automatically.</div></div><button class=\"btn green\" id=\"completeTodayBtn\">Complete Check-in ✓</button></div>\n  </section>\n\n"};
